import random

def generate_test_case():
    num_nodes = random.randint(0, 100)
    if num_nodes == 0:
        return []
    else:
        nodes = []
        for _ in range(num_nodes):
            node = random.randint(-100, 100)
            nodes.append(node if node != 0 else None)
        return nodes
